/**
 * Autogenerated file that mimics Antd style generators
 * Tailwind Token Output: turns the Token Source into Tailwind v4 `@theme` CSS.
 *
 * The stylesheets it produces are committed next to this file and published as
 * `@repo/ui/tokens/theme.css` (shared) and `@repo/ui/tokens/<theme>.css` (one per Theme).
 * Regenerate them with `pnpm --filter @repo/ui tokens` after changing the Token Source.
 */
import { brandPalette } from './brand-palette';
import { focusRing, sharedColors, themes, type Theme, type ThemeName } from './colors';
import { breakpoints, shadows } from './layout';
import { fontFamilies, textStyles, type TextStyleName } from './typography';

const header = (source: string) =>
  `/* Generated from the Token Source by ${source}. Do not edit by hand: run \`pnpm --filter @repo/ui tokens\`. */`;

const kebab = (name: string): string =>
  name.replace(/[A-Z]/g, (letter) => `-${letter.toLowerCase()}`);

/** `colorPrimaryBgHover` -> `primary-bg-hover`, the Tailwind colour name for an antd token. */
export const roleTokenName = (antdName: string): string =>
  kebab(antdName.replace(/^color/, '')).slice(1);

const rem = (px: number): string => `${px / 16}rem`;

const declarations = (entries: [string, string | number][]): string =>
  entries.map(([name, value]) => `  ${name}: ${value};`).join('\n');

/** `Object.entries` with typed keys; the library targets ES2015. */
const entriesOf = <T extends object>(object: T): [keyof T & string, T[keyof T]][] =>
  (Object.keys(object) as (keyof T & string)[]).map((key) => [key, object[key]]);

const flatten = <T>(lists: T[][]): T[] => ([] as T[]).concat(...lists);

const block = (selector: string, comment: string, entries: [string, string | number][]): string =>
  `${selector} {\n  /* ${comment} */\n${declarations(entries)}\n}`;

const brandPaletteEntries = (): [string, string][] =>
  flatten(
    entriesOf(brandPalette).map(([key, color]): [string, string][] => {
      const name = kebab(key);
      return [
        [`--color-${name}`, color.base],
        ...color.tints.map((tint, index): [string, string] => [
          `--color-${name}-tint-${index + 1}`,
          tint,
        ]),
      ];
    }),
  );

const roleEntries = (colors: Record<string, string>): [string, string][] =>
  entriesOf(colors)
    .filter(([key]) => key.startsWith('color'))
    .map(([key, value]): [string, string] => [`--color-${roleTokenName(key)}`, value]);

/** Tailwind `text-*` sizes that take antd's size and line height. */
const fontSizes = {
  xs: 'small',
  sm: 'body',
  base: 'heading5',
  xl: 'heading4',
  '2xl': 'heading3',
  '3xl': 'heading2',
  '4xl': 'heading1',
} as const satisfies Record<string, TextStyleName>;

const fontSizeEntries = (): [string, string][] =>
  flatten(
    entriesOf(fontSizes).map(([size, style]): [string, string][] => {
      const { fontSize, lineHeight } = textStyles[style];
      return [
        [`--text-${size}`, rem(fontSize)],
        [`--text-${size}--line-height`, `calc(${lineHeight} / ${fontSize})`],
      ];
    }),
  );

/** Tailwind breakpoint names with antd's widths (`2xl` is antd's `xxl`). */
const breakpointEntries = (): [string, string][] =>
  entriesOf(breakpoints).map(([name, px]): [string, string] => [
    `--breakpoint-${name === 'xxl' ? '2xl' : name}`,
    rem(px),
  ]);

/** One ready-made text-style utility per level: `heading-1` to `heading-5`, `body-text`, `small-text`. */
const textStyleUtilityName = (style: TextStyleName): string =>
  style.startsWith('heading') ? style.replace('heading', 'heading-') : `${style}-text`;

const textStyleUtilities = (): string =>
  (Object.keys(textStyles) as TextStyleName[])
    .map((style) => {
      const { fontFamily, fontSize, lineHeight, fontWeight } = textStyles[style];
      return `@utility ${textStyleUtilityName(style)} {\n${declarations([
        ['font-family', `--theme(--font-${fontFamily})`],
        ['color', '--theme(--color-text)'],
        ['font-weight', fontWeight],
        ['font-size', rem(fontSize)],
        ['line-height', `calc(${lineHeight} / ${fontSize})`],
      ])}\n}`;
    })
    .join('\n\n');

/** The shared stylesheet: every token except a Theme's primary and link colours. */
export const sharedThemeCss = (): string =>
  [
    header('src/tokens/tailwind.ts'),
    block(
      '@theme',
      'Brand Palette: decorative only; components use Role Tokens.',
      brandPaletteEntries(),
    ),
    block('@theme', 'Shared Role Tokens, named after antd tokens.', [
      ...roleEntries(sharedColors),
      ['--color-focus-ring-contrast', focusRing.contrastColor],
    ]),
    block('@theme', 'Typography: antd sizes and line heights, PCGL families.', [
      ['--font-heading', fontFamilies.heading],
      ['--font-body', fontFamilies.body],
      ...fontSizeEntries(),
    ]),
    block('@theme', 'Layout: antd breakpoints and shadows.', [
      ...breakpointEntries(),
      ['--shadow-sm', shadows.boxShadowTertiary],
      ['--shadow-md', shadows.boxShadow],
    ]),
    block('@theme', 'Focus ring: 2px outline, 2px offset.', [
      ['--focus-ring-width', `${focusRing.width}px`],
      ['--focus-ring-offset', `${focusRing.offset}px`],
    ]),
    textStyleUtilities(),
  ].join('\n\n') + '\n';

/** A Theme's stylesheet: the shared stylesheet plus that Theme's primary and link colours. */
export const themeCss = (name: ThemeName): string => {
  const theme: Theme = themes[name];
  return (
    [
      header('src/tokens/tailwind.ts'),
      "@import './theme.css';",
      block('@theme', `${theme.name} Theme.`, [
        ...roleEntries({ ...theme }),
        ['--color-focus-ring', theme.colorPrimary],
      ]),
    ].join('\n\n') + '\n'
  );
};

/** Every generated stylesheet, keyed by its file name in `src/tokens/`. */
export const tailwindTokenOutput = (): Record<string, string> =>
  (Object.keys(themes) as ThemeName[]).reduce<Record<string, string>>(
    (files, name) => ({ ...files, [`${name}.css`]: themeCss(name) }),
    { 'theme.css': sharedThemeCss() },
  );
